output:
cat > /etc/logstash/conf.d/syslog.conf << 'EOF'
input { beats { port => 5044 } }
filter {
  if [type] == "syslog" {
    grok { match => { "message" => "<%{POSINT:priority}>%{SYSLOGLINE}" } }
    date { match => [ "timestamp", "MMM  d HH:mm:ss", "MMM dd HH:mm:ss" ] }
  }
}
output { elasticsearch { hosts => ["localhost:9200"] } }
EOF && systemctl start logstash
